from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Locate the solid separator and use its end caps to identify the
    # enclosed (reference) side. The opposite side is edited.
    horizontal = [r for r in range(h) if len(set(g[r])) == 1]
    if horizontal:
        r = horizontal[len(horizontal)//2]
        line = g[r][0]
        top_framed = all(v == line for v in g[0])
        if top_framed:
            source, target, edge = r-1, r+1, h-1
            candidates = range(r+1, h)
        else:
            source, target, edge = r+1, r-1, 0
            candidates = range(r-1, -1, -1)
        # The edited pattern may begin a few cells beyond the separator.
        target = next(y for y in candidates
                      if any(g[y][c] != line for c in range(w)))
        background = Counter(g[target]).most_common(1)[0][0]
        for c in range(w):
            if g[source][c] == g[target][c]:
                value = g[source][c]
                if value != background:
                    g[target + (1 if top_framed else -1)][c] = value
            else:
                value = g[target][c]
                g[target][c] = background
                if value != background:
                    g[edge][c] = value
        return g

    c = next(c for c in range(w)
             if len(set(g[r][c] for r in range(h))) == 1)
    line = g[0][c]
    left_framed = all(g[0][x] == line for x in range(c+1))
    if left_framed:
        source, edge = c-1, w-1
        candidates = range(c+1, w)
    else:
        source, edge = c+1, 0
        candidates = range(c-1, -1, -1)
    target = next(x for x in candidates
                  if any(g[r][x] != line for r in range(h)))
    background = Counter(g[r][target] for r in range(h)).most_common(1)[0][0]
    for r in range(h):
        if g[r][source] == g[r][target]:
            value = g[r][source]
            if value != background:
                g[r][target + (1 if left_framed else -1)] = value
        else:
            value = g[r][target]
            g[r][target] = background
            if value != background:
                g[r][edge] = value
    return g
